package detector

import (
	"bytes"
	"context"
	"encoding/json"
	"os"
	"strings"
	"testing"

	"github.com/step-security/dev-machine-guard/internal/model"
)

// The shared contract is generated by the real Linux collectors and the Nix
// reader over one host: RPM with epochs, a partial dpkg, a failed apk, Flatpak
// user and system installations, and Nix multi-output, inactive, Home Manager,
// changed and unregistered sources. Durations are normalized.
func TestSystemPackageGoldenProducer(t *testing.T) {
	f := newSysPkgFake()
	f.rpm(rpmLine("bash", "(none)")+"\n"+rpmLine("shadow-utils", "2"), 0)
	f.dpkg(dpkgLine("coreutils", "installed")+"\nmalformed", 0)
	f.SetFile("/lib/apk/db/installed", nil)
	f.flatpak(flatpakFixtureRows, 0)
	f.flatpakInfo("--system", "stable", strings.Replace(flatpakInfoUser, "/root/.local/share/flatpak", "/var/lib/flatpak", 1), 0)
	r := newSysPkgRun()
	NewSystemPkgDetector(f, nil).scan(context.Background(), r)

	n := nixHost(model.PlatformLinux)
	n.links[nixSystemSW] = nixSW
	n.exists[nixSW] = true
	n.after = func(p string, i int) {
		if p == nixEnvDef+"/manifest.nix" && i == 1 {
			n.links[nixDefaultProfile+"-1-link"] = nixEnvLead
			n.exists[nixEnvLead] = true
		}
	}
	runNix(t, n, nil, r)
	for i := range r.scans {
		r.scans[i].ScanDurationMs = 0
	}
	pair := struct {
		Scans     []model.SystemPackageScanResult `json:"system_package_scans"`
		Inventory *model.SystemPackageInventory   `json:"system_package_inventory"`
	}{r.scans, &model.SystemPackageInventory{SchemaVersion: model.SystemPackageInventorySchemaVersion, DiscoveryRoots: r.roots}}
	raw, err := json.MarshalIndent(pair, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	raw = append(raw, '\n')
	path := "../model/testdata/system_package_inventory_v1_golden.json"
	if os.Getenv("UPDATE_SYSTEM_PACKAGE_GOLDEN") == "1" {
		if err := os.WriteFile(path, raw, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	want, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(raw, want) {
		t.Fatal("producer differs from shared system package golden; review the contract before regenerating")
	}
}
